const programs={producto:{title:'De la idea a producción',description:'Para personas con bases de programación que quieren conectar desarrollo de software con una entrega útil para un usuario real.',project:'Un producto web desplegado, con repositorio documentado, pruebas del flujo principal y una presentación que demuestre el valor aportado.',modules:['Problema, usuario y criterios de aceptación','Diseño de la solución y decisiones de arquitectura','Desarrollo e integración del producto','Pruebas, seguridad básica y experiencia de uso','Despliegue, observabilidad y presentación final']},cloud:{title:'Sistemas listos para operar',description:'Para desarrolladores y profesionales de sistemas con conocimientos de Git, terminal y servicios web.',project:'Un servicio desplegado con un pipeline de integración y entrega, monitoreo, gestión de configuración y un procedimiento de recuperación.',modules:['Fundamentos de infraestructura y entornos','Contenedores y configuración segura','Integración continua y despliegue automatizado','Métricas, logs y alertas','Respaldo, recuperación y manual de operación']},ia:{title:'IA que resuelve trabajo real',description:'Para profesionales que quieren entender y aplicar IA a un proceso concreto. Los requisitos técnicos se definirán al cerrar el temario.',project:'Un flujo automatizado con IA, supervisión humana, casos de evaluación y una comparación del proceso antes y después.',modules:['Selección del problema y mapa del proceso','Fundamentos de IA y límites de uso','Diseño del flujo y conexión de herramientas','Evaluación, privacidad y supervisión humana','Medición del resultado y entrega del caso']}};
const dialog=document.querySelector('#course-dialog');
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(other=>{const selected=other===button;other.classList.toggle('active',selected);other.setAttribute('aria-pressed',String(selected));});document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter;});}));
document.querySelectorAll('[data-course]').forEach(button=>button.addEventListener('click',()=>{const p=programs[button.dataset.course];document.querySelector('#dialog-title').textContent=p.title;document.querySelector('#dialog-description').textContent=p.description;document.querySelector('#dialog-project').textContent=p.project;document.querySelector('#dialog-modules').replaceChildren(...p.modules.map(label=>{const li=document.createElement('li');li.textContent=label;return li;}));document.querySelector('#goal').value=button.dataset.course;dialog.showModal();}));
document.querySelector('.close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
document.querySelector('.dialog-route').addEventListener('click',()=>{dialog.close();document.querySelector('#ruta').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelector('#goal').focus({preventScroll:true});});
document.querySelector('#route-form').addEventListener('submit',event=>{event.preventDefault();const key=document.querySelector('#goal').value;document.querySelector('#route-result').textContent=`Tu ruta sugerida: ${programs[key].title}. ${key==='producto'?'Empieza reforzando programación, Git y fundamentos web.':key==='cloud'?'Empieza por Git, terminal, redes y servicios web.':'Empieza identificando un proceso repetitivo y definiendo cómo medir su mejora.'} Programa en diseño; todavía no hay inscripciones.`;});
document.querySelector('#year').textContent=new Date().getFullYear();

const paletteSelect=document.querySelector('#palette');
const paletteNames={energia:'Energía y precisión',tecnologia:'Tecnología global',premium:'Academia premium'};
paletteSelect.value=document.documentElement.dataset.palette||'energia';
paletteSelect.addEventListener('change',()=>{
  const value=paletteSelect.value;
  if(!Object.hasOwn(paletteNames,value))return;
  document.documentElement.dataset.palette=value;
  let saved=false;
  try{localStorage.setItem('rtd-palette',value);saved=true;}catch{}
  document.querySelector('#palette-status').textContent=`${paletteNames[value]} aplicada${saved?' · Guardada en este navegador':''}`;
});
